import json

from .money import fmt
from .report import MonthAgg
from .transactions import Transaction


def _table(headers: list[str], aligns: str, rows: list[list[str]]) -> str:
    widths = [max([len(h)] + [len(r[i]) for r in rows]) for i, h in enumerate(headers)]

    def line(cells: list[str]) -> str:
        parts = [
            c.ljust(w) if a == "l" else c.rjust(w)
            for c, w, a in zip(cells, widths, aligns)
        ]
        return "  ".join(parts).rstrip() + "\n"

    out = [line(headers), line(["-" * w for w in widths])]
    out.extend(line(r) for r in rows)
    return "".join(out)


def _json(obj: object) -> str:
    return json.dumps(obj, indent=2, ensure_ascii=False) + "\n"


def render_report(months: list[MonthAgg], output_format: str) -> str:
    if output_format == "json":
        return _json(
            {
                "months": [
                    {
                        "month": m.month,
                        "count": m.count,
                        "income": fmt(m.income),
                        "expenses": fmt(m.expenses),
                        "net": fmt(m.net),
                        "categories": [
                            {
                                "category": c.category,
                                "count": c.count,
                                "income": fmt(c.income),
                                "expenses": fmt(c.expenses),
                                "net": fmt(c.net),
                            }
                            for c in m.categories
                        ],
                    }
                    for m in months
                ]
            }
        )
    rows = [
        [m.month, c.category, str(c.count), fmt(c.income), fmt(c.expenses), fmt(c.net)]
        for m in months
        for c in m.categories
    ]
    return _table(
        ["MONTH", "CATEGORY", "COUNT", "INCOME", "EXPENSES", "NET"], "llrrrr", rows
    )


def render_categorize(
    pairs: list[tuple[Transaction, str]], output_format: str
) -> str:
    if output_format == "json":
        return _json(
            {
                "transactions": [
                    {
                        "date": t.date,
                        "description": t.description,
                        "amount": fmt(t.amount),
                        "category": cat,
                    }
                    for t, cat in pairs
                ]
            }
        )
    rows = [[t.date, fmt(t.amount), cat, t.description] for t, cat in pairs]
    return _table(["DATE", "AMOUNT", "CATEGORY", "DESCRIPTION"], "lrll", rows)

